import { DevicePreview } from "march/ui"

// DevicePreview'un özellikleri: device (hazır ad ya da kendi DeviceSpec'in), landscape, touch, fit, fitHeight, label,
// statusBar, time, homeIndicator, camera, class ve içerik (src ile bir adres de gösterilebilir)
const watch = { name: "Saat", width: 198, height: 242, radius: 48, kind: "screen" as const, camera: "none" as const }

export function DevicePreviewLab() {
  return <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
    <DevicePreview class="lab-phone" device="iphone-se" label="Küçük telefon" touch={false} statusBar={false} homeIndicator={false} camera={false} fitHeight={360}>
      <p sx={{ p: 2 }}>Çubuksuz ekran</p>
    </DevicePreview>
    <DevicePreview class="lab-own" device={watch} fit={false} time="10:10">
      <p sx={{ p: 2, text: "sm" }}>Kendi cihazım</p>
    </DevicePreview>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DevicePreviewLab } from "./DevicePreviewLab.tsx"

// DevicePreviewLab'in testleri: kaydedince Testler sekmesinde çalışır
test("içerik cihazın ekranında", () => {
  const s = renderTest(() => <DevicePreviewLab />)
  expect(s.get(".lab-phone")?.textContent).toContain("Çubuksuz ekran")
  expect(s.get(".lab-own")?.textContent).toContain("Kendi cihazım")
})

test("label erişilebilir ad olur", () => {
  const s = renderTest(() => <DevicePreviewLab />)
  expect(s.get(".lab-phone")?.outerHTML).toContain("Küçük telefon")
})
